 */
@font-face {
  font-family: "Zhuque Fangsong";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

@font-face {
  font-family: "Cormorant SC";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

:root {
  --mj-paper: #fbf6ee;
  --mj-paper-deep: #f0e5d7;
  --mj-paper-white: #fffaf2;
  --mj-paper-red: #f7e8e3;
  --mj-ink: #392824;
  --mj-muted: #80685d;
  --mj-red: #b32634;
  --mj-red-deep: #8e1d29;
  --mj-red-soft: #d37076;
  --mj-red-wash: rgba(179, 38, 52, 0.09);
  --mj-green: #6f7f5e;
  --mj-green-deep: #536345;
  --mj-green-wash: rgba(111, 127, 94, 0.11);
  --mj-gold: #ad8a53;
  --mj-line: rgba(179, 38, 52, 0.52);
  --mj-line-soft: rgba(111, 127, 94, 0.38);
  --mj-shadow: 0 1.25rem 3rem rgba(87, 47, 39, 0.12);
  --mj-radius: 0.15rem;
  --mj-avatar-size: clamp(4.75rem, 7vw, 6.25rem);
  --mj-avatar-gap: 0rem;
  --mj-avatar-slot: calc(42% + var(--mj-avatar-gap));
  --mj-font-body: "Zhuque Fangsong", "FangSong", "STFangsong", "Noto Serif SC", serif;
  --mj-font-display: "Cormorant SC", "Zhuque Fangsong", "Noto Serif SC", serif;

  /* Keep SillyTavern's layout calculations in lockstep with the themed bars. */
  --topBarBlockSize: 4.35rem;
  --bottomFormBlockSize: 3.8rem;

  --mj-botanical: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/strawberry-botanical.png");
  --mj-icon-ai: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/ai-quill.webp");
  --mj-icon-connection: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/connection-jam.webp");
  --mj-icon-format: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/format-book.webp");
  --mj-icon-worldbook: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/worldbook-globe.webp");
  --mj-icon-settings: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/settings-key.webp");
  --mj-icon-background: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/background-frame.webp");
  --mj-icon-extensions: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/extensions-puzzle.webp");
  --mj-icon-persona: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/persona-locket.webp");
  --mj-icon-characters: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/characters-folios.webp");
  --mj-icon-menu: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/menu-ribbon.webp");
  --mj-icon-magic: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/magic-wand.webp");
  --mj-icon-send: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/db94e20302d60468bf052116cb35c87ef66431a8/assets/%E8%8E%93%E7%AC%BA%E7%95%99%E7%99%BD/icons/send-plane.webp");

  --SmartThemeBodyColor: var(--mj-ink);
  --SmartThemeEmColor: var(--mj-green);
  --SmartThemeUnderlineColor: var(--mj-red);
  --SmartThemeQuoteColor: var(--mj-green);
  --SmartThemeBlurTintColor: var(--mj-paper-white);
  --SmartThemeChatTintColor: var(--mj-paper);
  --SmartThemeUserMesBlurTintColor: var(--mj-paper-red);
  --SmartThemeBotMesBlurTintColor: var(--mj-paper);
  --SmartThemeBorderColor: var(--mj-line);
  --mainFontFamily: var(--mj-font-body);
}

body {
  color: var(--mj-ink);
  background-color: var(--mj-paper-deep);
  font-family: var(--mj-font-body);
  text-shadow: none;
}

#bg1,
#bg_custom {
  background-color: var(--mj-paper-deep);
}

/* ===== src/kernel/protection.css ===== */
/* Functional protection: decorative layers never intercept interaction. */
#chat .mes_block::before,
#chat .mes_block::after,
#chat .ch_name::before,
#send_form::before,
#top-settings-holder .drawer-icon::after {
  pointer-events: none;
}

#chat :is(.mes_buttons, .mes_edit_buttons, .mes_reasoning_actions),
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate),
#top-settings-holder .drawer-toggle {
  position: relative;
  z-index: 2;
}

#chat :is(.mes_text, .mes_reasoning, .mes_media_wrapper, .mes_file_wrapper) {
  min-width: 0;
}

#chat :is(pre, table, img, video, audio) { max-width: 100%; }

#chat pre,
#chat .mes_text table { overflow-x: auto; }

@media (prefers-reduced-motion: reduce) {
  #chat .mes,
  #send_form,
  #top-settings-holder .drawer-icon,
  .drawer-content {
    transition: none !important;
    animation: none !important;
  }
}

/* ===== src/kernel/scrollbars.css ===== */
/* Global scrollbar appearance kernel: scrolling remains functional. */
::-webkit-scrollbar {
  display: none !important;
}

* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

/* ===== src/chat-layout.css ===== */
/* W01: reference-led editorial chat master. */
#chat {
  padding: clamp(0.85rem, 1.8vw, 1.6rem) clamp(0.75rem, 4.2vw, 4.8rem) 1.2rem;
  color: var(--mj-ink);
  background-color: var(--mj-paper);
  background-image:
    linear-gradient(90deg, transparent 0 97.8%, rgba(179, 38, 52, 0.09) 97.8% 98%, transparent 98%),
    linear-gradient(180deg, rgba(255, 250, 242, 0.78), transparent 32%);
  border: 0;
  text-shadow: none;
}

#chat .mes {
  position: relative;
  flex: 0 0 auto;
  width: min(100%, 82rem);
  min-height: 0;
  margin-inline: auto;
  color: var(--mj-ink);
  background: transparent;
  border-radius: 0;
  box-shadow: none;
  text-shadow: none;
}

/* Keep delete-mode function nodes out of the User grid's auto-placement flow. */
#chat .mes > .for_checkbox,
#chat .mes > input.del_checkbox {
  position: absolute;
  top: 0.72rem;
  left: 0.72rem;
  z-index: 5;
  margin: 0;
}

#chat .mes > input.del_checkbox {
  width: 1.1rem;
  height: 1.1rem;
  appearance: none;
  background: var(--mj-paper-white);
  border: 1px solid var(--mj-green);
  border-radius: 0;
  box-shadow: none;
  opacity: 0.86;
}

#chat .mes > input.del_checkbox:checked {
  background: var(--mj-red);
  border-color: var(--mj-red-deep);
  box-shadow: inset 0 0 0 0.2rem var(--mj-paper-white);
}

#chat .mes > input.del_checkbox:focus-visible {
  outline: 1px solid var(--mj-red-deep);
  outline-offset: 0.16rem;
}

/* User: retain the real avatar as a compact editorial mark; message height follows content. */
#chat .mes[is_user="true"] {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--mj-avatar-size);
  grid-template-rows: auto;
  align-items: start;
  gap: var(--mj-avatar-gap);
  padding: 0;
  margin-block: 0 clamp(1.9rem, 4vw, 4rem);
  background: var(--mj-paper-white);
  border-block: 1px solid var(--mj-line);
  overflow: hidden;
}

#chat .mes[is_user="true"] .mesAvatarWrapper {
  position: relative;
  grid-column: 2;
  grid-row: 1;
  align-self: start;
  width: var(--mj-avatar-size);
  min-width: 0;
  min-height: 0;
  aspect-ratio: 1 / 1;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border-left: 1px solid var(--mj-line);
  background: var(--mj-red-deep);
  box-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
  position: absolute;
  inset: 0;
  width: 100% !important;
  height: 100% !important;
  margin: 0;
  border: 0;
  border-radius: 0 !important;
  box-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
  overflow: hidden;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  max-width: none;
  border: 0;
  border-radius: 0 !important;
  box-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
  text-shadow: none !important;
  image-rendering: -webkit-optimize-contrast;
  image-rendering: high-quality;
  object-fit: cover;
  object-position: 50% 35%;
}

#chat .mes[is_user="true"] .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
  position: relative;
  z-index: 1;
  float: right;
  margin: 0.45rem 0.45rem 0 0;
  padding: 0.12em 0.38em;
  color: var(--mj-paper-white);
  background: rgba(57, 40, 36, 0.72);
  border: 1px solid rgba(255, 250, 242, 0.34);
  font-family: var(--mj-font-display);
  font-size: 0.7em;
  text-shadow: none;
}

#chat .mes[is_user="true"] .mes_block {
  grid-column: 1;
  grid-row: 1;
  display: flex;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: clamp(1rem, 2.2vw, 1.8rem) clamp(1.1rem, 3vw, 2.2rem);
  flex-direction: column;
  justify-content: flex-start;
  overflow: visible;
}

#chat .mes[is_user="true"] .ch_name {
  padding: 0 0 0.8rem;
  margin: 0 0 0.8rem;
  color: var(--mj-red);
  border-bottom: 1px solid var(--mj-line);
}

#chat .mes[is_user="true"] .ch_name::before {
  content: "USER";
  margin-right: 0.8em;
  color: var(--mj-red);
  font-family: var(--mj-font-display);
  font-size: 0.88em;
  letter-spacing: 0.16em;
}

#chat .mes[is_user="true"] .mes_text {
  width: 100%;
  padding: 0;
  font-size: 1em;
  line-height: 1.95;
}

/* Character: no avatar slot; full reading page with a narrow botanical note rail. */
#chat .mes[is_user="false"][is_system="false"] {
  padding: clamp(0.2rem, 0.7vw, 0.6rem) 0 clamp(1.5rem, 2.8vw, 2.6rem);
  margin-bottom: clamp(1.15rem, 2.2vw, 2rem);
  background: transparent;
  border-bottom: 1px solid var(--mj-line);
}

#chat .mes[is_user="false"] .mesAvatarWrapper,
#chat .mes[is_system="true"] .mesAvatarWrapper {
  display: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block {
  position: relative;
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  margin: 0;
  padding: 0;
  overflow: visible;
}

#chat .mes.last_mes[is_user="false"][is_system="false"] .mes_block {
  padding-right: clamp(4.8rem, 8vw, 7rem);
}

#chat .mes.last_mes[is_user="false"][is_system="false"] .mes_block::before {
  content: "莓熟未言，风止心动。";
  position: absolute;
  top: clamp(5.1rem, 7vw, 6.5rem);
  right: clamp(0.3rem, 1.1vw, 1rem);
  padding-left: 0.55em;
  color: var(--mj-green-deep);
  border-left: 1px solid var(--mj-line-soft);
  font-family: var(--mj-font-body);
  font-size: 0.76em;
  letter-spacing: 0.28em;
  line-height: 1.85;
  writing-mode: vertical-rl;
}

#chat .mes.last_mes[is_user="false"][is_system="false"] .mes_block::after {
  content: "";
  position: absolute;
  top: 1rem;
  right: 0;
  width: clamp(3.4rem, 5.5vw, 5rem);
  height: clamp(4.2rem, 7vw, 6.4rem);
  background-color: transparent;
  background-image: var(--mj-botanical);
  background-repeat: no-repeat;
  background-position: 50% 8%;
  background-size: 94% auto;
  border-bottom: 1px solid var(--mj-line-soft);
  opacity: 0.9;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
  padding: 0 0 0.8rem;
  margin: 0 0 clamp(0.9rem, 1.8vw, 1.5rem);
  color: var(--mj-red);
  border-bottom: 1px solid rgba(179, 38, 52, 0.25);
}

#chat .mes[is_user="false"][is_system="false"] .ch_name::before {
  content: "CHARACTER";
  margin-right: 0.75em;
  color: var(--mj-red);
  font-family: var(--mj-font-display);
  font-size: 0.84em;
  letter-spacing: 0.13em;
}

#chat .mes .name_text {
  color: var(--mj-red);
  font-weight: 400;
  letter-spacing: 0.08em;
}

#chat .mes :is(.timestamp, .mesIDDisplay, .mes_timer, .tokenCounterDisplay, .swipes-counter) {
  color: var(--mj-muted);
  font-family: var(--mj-font-display);
  font-size: 0.78em;
  opacity: 1;
  text-shadow: none;
}

#chat :is(.mes_buttons, .mes_edit_buttons) {
  color: var(--mj-red);
  text-shadow: none;
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button) {
  color: var(--mj-red);
  background: transparent;
  border: 0;
  opacity: 0.72;
  filter: none;
  text-shadow: none;
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button):is(:hover, :focus-visible) {
  color: var(--mj-red-deep);
  opacity: 1;
  outline: 1px solid var(--mj-red-soft);
  outline-offset: 0.18rem;
}

#chat .mes[is_system="true"] {
  width: min(100%, 78ch);
  margin: 0 auto 1.5rem;
  padding: 0.75rem 1rem;
  color: var(--mj-green-deep);
  background: var(--mj-green-wash);
  border: 1px solid var(--mj-line-soft);
  border-left: 0.22rem solid var(--mj-green);
}

#chat .mes[is_system="true"] .mes_block {
  width: 100%;
  margin: 0;
  padding: 0;
}

body.documentstyle #chat .mes .mes_block,
body.documentstyle #chat .mes .mes_text,
body.documentstyle #chat .last_mes .mes_text {
  margin-left: 0;
  margin-right: 0;
}

/* ===== src/full-text.css ===== */
/* T02: airy Fangsong editorial full-text language. */
#chat .mes_text {
  width: 100%;
  max-width: none;
  color: var(--mj-ink);
  font-family: var(--mj-font-body);
  font-size: 1em;
  font-weight: 400;
  line-height: 2.08;
  letter-spacing: 0.055em;
  overflow-wrap: anywhere;
}

/* Approved reading format: Character prose stays in a centered normal-width column. */
#chat .mes[is_user="false"][is_system="false"] .mes_text {
  width: min(100%, 48rem);
  max-width: 48rem;
  margin-right: auto;
  margin-left: auto;
}

#chat .mes[is_user="false"][is_system="false"] .mes_reasoning_details {
  margin-right: auto;
  margin-left: auto;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
  color: var(--mj-red);
  font-family: var(--mj-font-body);
  font-weight: 400;
  letter-spacing: 0.14em;
  line-height: 1.5;
  text-wrap: balance;
}

#chat .mes_text h1 {
  padding-bottom: 0.4em;
  border-bottom: 1px solid var(--mj-line);
  font-size: 1.55em;
}

#chat .mes_text :is(h2, h3) {
  font-size: 1.2em;
}

#chat .mes_text p {
  margin: 0 0 1.08em;
}

#chat .mes_text blockquote {
  margin: 1.4em 0;
  padding: 0.75em 1.2em;
  color: var(--mj-ink);
  background: var(--mj-paper-red);
  border: 0;
  border-left: 0.16rem solid var(--mj-red);
}

#chat .mes_text :is(em, i) { color: var(--mj-green-deep); }

#chat .mes_text :is(strong, b) {
  color: var(--mj-red-deep);
  font-weight: 400;
  letter-spacing: 0.09em;
}

#chat .mes_text a {
  color: var(--mj-red);
  text-decoration-color: var(--mj-red-soft);
  text-underline-offset: 0.24em;
}

#chat .mes_text hr {
  width: min(42%, 16rem);
  height: 1px;
  margin: 1.9em auto;
  background: var(--mj-red);
  opacity: 0.55;
}

#chat .mes_text :is(code, kbd) {
  color: var(--mj-ink);
  background: var(--mj-paper-deep);
  border: 1px solid var(--mj-line-soft);
  border-radius: 0;
  text-shadow: none;
}

#chat .mes_text pre {
  padding: 1em 1.1em;
  color: var(--mj-ink);
  background: var(--mj-paper-deep);
  border: 1px solid var(--mj-line-soft);
  border-left: 0.18rem solid var(--mj-green);
  border-radius: 0;
  box-shadow: none;
}

#chat .mes_text table {
  width: 100%;
  border-collapse: collapse;
  background: var(--mj-paper-white);
}

#chat .mes_text :is(th, td) {
  padding: 0.58em 0.75em;
  border: 1px solid var(--mj-line-soft);
}

#chat .mes_text th {
  color: var(--mj-red);
  background: var(--mj-paper-red);
  font-weight: 400;
  letter-spacing: 0.08em;
}

#chat .mes_reasoning_details {
  box-sizing: border-box;
  width: min(100%, 42rem);
  max-width: 100%;
  margin: 0 0 1rem;
  padding: 0;
  color: var(--mj-green-deep);
  background: var(--mj-paper-white);
  border: 1px solid var(--mj-line-soft);
  border-left: 0.16rem solid var(--mj-red);
  border-radius: 0;
  box-shadow: none;
}

#chat .mes_reasoning_details > .mes_reasoning_summary {
  display: flex;
  align-items: center;
  width: 100%;
  margin: 0;
  padding: 0;
  color: var(--mj-green-deep);
  background: transparent;
  list-style: none;
  text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_header_block {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
}

#chat .mes_reasoning_details .mes_reasoning_header {
  box-sizing: border-box;
  width: 100%;
  margin: 0;
  padding: 0.58em 2.4em 0.58em 0.9em;
  color: var(--mj-green-deep);
  background: transparent !important;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  filter: none;
  font-family: var(--mj-font-body);
  font-weight: 400;
  letter-spacing: 0.08em;
  text-shadow: none;
}

#chat .mes_reasoning_details[open] .mes_reasoning_header {
  background: var(--mj-paper-red) !important;
  border-bottom: 1px solid var(--mj-line-soft);
}

#chat .mes_reasoning_details :is(.mes_reasoning_header_title, .mes_reasoning_arrow) {
  color: var(--mj-green-deep);
  text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning {
  margin: 0;
  padding: 0.75em 0.9em 0.8em 1em;
  color: var(--mj-green-deep);
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  font-family: var(--mj-font-body);
  font-weight: 400;
  line-height: 1.9;
  text-shadow: none;
}

/* ===== src/windows/topbar.css ===== */
/* W02: nine distinct unframed theme objects; native glyph remains as fallback. */
#top-bar,
#top-settings-holder {
  color: var(--mj-ink);
  background-color: var(--mj-paper-white);
  background-image: none;
  border-bottom: 1px solid var(--mj-line);
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

#top-settings-holder {
  height: var(--topBarBlockSize);
  min-height: var(--topBarBlockSize);
  align-items: stretch;
}

#top-bar { height: var(--topBarBlockSize); }

#top-settings-holder .drawer-toggle {
  width: 100%;
  height: 100%;
  min-height: calc(var(--topBarBlockSize) - 0.1rem);
  display: flex;
  align-items: stretch;
  justify-content: center;
  border-right: 1px solid rgba(179, 38, 52, 0.21);
}

#top-settings-holder .drawer:last-child .drawer-toggle { border-right: 0; }

/*
 * Desktop three-axis track:
 * - the .drawer parents keep SillyTavern's native geometry;
 * - only their direct trigger layer is positioned;
 * - Parameter/Character occupy the same outer columns as fillLeft/fillRight;
 * - the seven center triggers divide the 64vw chat axis evenly.
 */
@media (min-width: 701px) {
  body:not(.movingUI) #top-bar {
    width: 100dvw;
  }

  body:not(.movingUI) #top-settings-holder > .drawer > .drawer-toggle {
    position: absolute;
    top: 0;
    bottom: 0;
    width: calc(100% / 7);
    height: auto;
  }

  body:not(.movingUI) #top-settings-holder > #ai-config-button > .drawer-toggle {
    left: calc((var(--sheldWidth) - 100dvw + 2px) / 2);
    width: calc((100dvw - var(--sheldWidth) - 2px) / 2);
  }

  body:not(.movingUI) #top-settings-holder > #sys-settings-button > .drawer-toggle { left: 0; }
  body:not(.movingUI) #top-settings-holder > #advanced-formatting-button > .drawer-toggle { left: 14.285714%; }
  body:not(.movingUI) #top-settings-holder > #WI-SP-button > .drawer-toggle { left: 28.571429%; }
  body:not(.movingUI) #top-settings-holder > #user-settings-button > .drawer-toggle { left: 42.857143%; }
  body:not(.movingUI) #top-settings-holder > #backgrounds-button > .drawer-toggle { left: 57.142857%; }
  body:not(.movingUI) #top-settings-holder > #extensions-settings-button > .drawer-toggle { left: 71.428571%; }
  body:not(.movingUI) #top-settings-holder > #persona-management-button > .drawer-toggle { left: 85.714286%; }

  body:not(.movingUI) #top-settings-holder > #rightNavHolder > .drawer-toggle {
    left: 100%;
    width: calc((100dvw - var(--sheldWidth) - 2px) / 2);
  }
}

#top-settings-holder .drawer-icon {
  position: relative;
  width: 100%;
  min-width: 3.7rem;
  min-height: calc(var(--topBarBlockSize) - 0.1rem);
  padding: 2.76rem 0.2rem 0.28rem;
  color: rgba(179, 38, 52, 0.2);
  background-color: transparent;
  background-repeat: no-repeat;
  background-position: 50% 0.16rem;
  background-size: 2.58rem 2.58rem;
  border: 0;
  opacity: 1;
  filter: none;
  text-align: center;
  text-shadow: none;
  transition: transform 160ms ease, background-size 160ms ease, box-shadow 160ms ease;
}

#top-settings-holder .drawer-icon::before {
  content: "" !important;
  display: none !important;
}

#top-settings-holder .drawer-icon::after {
  position: absolute;
  right: 0.1rem;
  bottom: 0.22rem;
  left: 0.1rem;
  color: var(--mj-ink);
  font-family: var(--mj-font-body);
  font-size: 0.74rem;
  letter-spacing: 0.08em;
  line-height: 1;
  white-space: nowrap;
}

#ai-config-button .drawer-icon { background-image: var(--mj-icon-ai); }
#sys-settings-button .drawer-icon { background-image: var(--mj-icon-connection); }
#advanced-formatting-button .drawer-icon { background-image: var(--mj-icon-format); }
#WI-SP-button .drawer-icon { background-image: var(--mj-icon-worldbook); }
#user-settings-button .drawer-icon { background-image: var(--mj-icon-settings); }
#backgrounds-button .drawer-icon { background-image: var(--mj-icon-background); }
#extensions-settings-button .drawer-icon { background-image: var(--mj-icon-extensions); }
#persona-management-button .drawer-icon { background-image: var(--mj-icon-persona); }
#rightNavHolder .drawer-icon { background-image: var(--mj-icon-characters); }

#ai-config-button .drawer-icon::after { content: "参数"; }
