/* ===== src/windows/controls.css ===== */
/* Shared visual state matrix, bounded to the nine core windows and popups.
 * chat_width=64 defines the center. Both fixed side roots reuse the official
 * dynamic-viewport formula and opposite anchors so presets/characters mirror. */
@media (min-width: 701px) {
  body:not(.movingUI)
    :is(#left-nav-panel.drawer-content.fillLeft, #right-nav-panel.drawer-content.fillRight) {
    box-sizing: border-box;
    top: var(--topBarBlockSize);
    width: calc((100dvw - var(--sheldWidth) - 2px) / 2);
    max-height: calc(100dvh - var(--topBarBlockSize));
  }

  body:not(.movingUI) #left-nav-panel.drawer-content.fillLeft {
    right: auto;
    left: 0;
  }

  body:not(.movingUI) #right-nav-panel.drawer-content.fillRight {
    right: 0;
    left: auto;
  }

  body:not(.movingUI)
    :is(#left-nav-panel.drawer-content.fillLeft, #right-nav-panel.drawer-content.fillRight).openDrawer {
    height: calc(100dvh - var(--topBarBlockSize));
    overflow: hidden;
  }

  body:not(.movingUI)
    :is(#left-nav-panel.drawer-content.fillLeft, #right-nav-panel.drawer-content.fillRight)
    .scrollableInner {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    padding: 0.65rem 0.8rem;
    overflow-x: hidden;
    overflow-y: auto;
  }
}

