  --ac-style-color-keyword: var(--mj-red-deep);
  color: var(--mj-ink);
  background: var(--mj-paper-white) !important;
  border-color: var(--mj-line) !important;
  border-radius: 0 !important;
  box-shadow: var(--mj-shadow);
  backdrop-filter: none;
  text-shadow: none;
}

body .ui-autocomplete,
body .ui-menu {
  color: var(--mj-ink);
  background: var(--mj-paper-white) !important;
  border: 1px solid var(--mj-line) !important;
  border-radius: 0 !important;
  box-shadow: var(--mj-shadow);
  font-family: var(--mj-font-body);
}

body .ui-menu :is(.ui-menu-item-wrapper, .ui-state-active, .ui-state-focus) {
  color: var(--mj-ink);
  background: var(--mj-paper-white);
  border-color: transparent;
}

body .ui-menu :is(.ui-state-active, .ui-state-focus) {
  color: var(--mj-paper-white);
  background: var(--mj-red) !important;
  border-color: var(--mj-red-deep) !important;
}

/* Pagination, scroll thumbs and slider handles complete the micro-control language. */
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup)
  .paginationjs-pages ul li a {
  color: var(--mj-red-deep);
  background: var(--mj-paper-white);
  border-color: var(--mj-line-soft);
  border-radius: 0;
  box-shadow: none;
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup)
  .paginationjs-pages ul li:is(.active, :hover, :focus-within) a {
  color: var(--mj-paper-white);
  background: var(--mj-red);
  border-color: var(--mj-red-deep);
}

:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, .popup)
  .paginationjs-pages ul li.disabled a {
  color: var(--mj-muted);
  background: var(--mj-paper-deep);
  opacity: 0.72;
}

body .ui-slider-handle,
body .ui-slider-handle.ui-state-default {
  color: var(--mj-paper-white) !important;
  background: var(--mj-red) !important;
  border: 0.16rem solid var(--mj-paper-white) !important;
  border-radius: 50% !important;
  outline: 1px solid var(--mj-green-deep) !important;
  box-shadow: none !important;
  filter: none !important;
  text-shadow: none !important;
}

/* ===== src/windows/world-info.css ===== */
/* W07: line-free index archive */
#WorldInfo {
  color: var(--mj-ink);
  background: rgba(248, 243, 237, 0.99);
  border: 0;
  border-radius: var(--mj-radius);
  box-shadow: none;
  backdrop-filter: none;
}

#WorldInfo :is(h3, h4, .standoutHeader, .inline-drawer-header) {
  color: var(--mj-red);
  background: transparent;
  border: 0;
  font-weight: 400;
  letter-spacing: 0.07em;
  box-shadow: none;
  text-shadow: none;
}

#WorldInfo .world_entry {
  margin-block: 0.7rem;
  padding: 0;
  color: var(--mj-ink);
  background: transparent;
  border: 0;
  box-shadow: none;
}

#WorldInfo .world_entry > .world_entry_form.wi-card-entry {
  padding: 0.78rem 0.9rem;
  background: rgba(179, 38, 52, 0.045);
  border: 0;
  border-radius: 0.2rem;
  box-shadow: none;
}

#WorldInfo .world_entry:nth-child(even) > .world_entry_form.wi-card-entry {
  background: rgba(111, 128, 98, 0.055);
}

#WorldInfo .world_entry :is(.inline-drawer, .inline-drawer-content) {
  background: transparent;
  border: 0;
  box-shadow: none;
}

#WorldInfo .world_entry .inline-drawer-header {
  padding-block: 0.3rem;
  background: rgba(255, 253, 249, 0.5);
  border: 0;
}

#WorldInfo :is(input:not([type="checkbox"]):not([type="radio"]), textarea, select, .text_pole) {
  color: var(--mj-ink);
  background: rgba(255, 253, 249, 0.92) !important;
  border: 0 !important;
  border-radius: 0.2rem !important;
  box-shadow: none;
}

#WorldInfo :is(input, textarea, select, .text_pole):focus-visible {
  outline: 1px solid var(--mj-red) !important;
  outline-offset: 1px;
}

#WorldInfo :is(input[type="checkbox"], input[type="radio"]) {
  accent-color: var(--mj-green);
}

#WorldInfo :is(.menu_button, .menu_button_icon, button) {
  color: var(--mj-red);
  background-color: rgba(179, 38, 52, 0.075);
  border: 0;
  border-radius: 0.2rem;
  box-shadow: none;
  text-shadow: none;
  filter: none;
}

#WorldInfo :is(.menu_button, .menu_button_icon, button):is(:hover, :focus-visible) {
  color: var(--mj-paper-white);
  background-color: var(--mj-red);
}

#WorldInfo #world_info_pagination {
  color: var(--mj-green);
}

/* ===== src/windows/mobile.css ===== */
/* W14: mobile model follows the recorded one-column avatar slot. */
@media (max-width: 700px) {
  :root {
    --mj-avatar-size: auto;
    --mj-avatar-slot: 100%;
    --mj-mobile-reading-padding: clamp(0.9rem, 4vw, 1.15rem);
    --mj-mobile-reading-width: min(calc(100% - 1.1rem), 36rem);
    --topBarBlockSize: 3.35rem;
    --bottomFormBlockSize: 2.85rem;
  }

  #top-settings-holder { min-height: 3.35rem; }

  #top-settings-holder .drawer-toggle,
  #top-settings-holder .drawer-icon {
    min-height: 3.35rem;
  }

  #top-settings-holder .drawer-icon {
    min-width: 0;
    padding: 0;
    background-position: center;
    background-size: clamp(1.75rem, 7.2vw, 2.45rem);
  }

  #top-settings-holder .drawer-icon::after { display: none; }

  #top-settings-holder .drawer-icon:is(:hover, :focus-visible, .openIcon) {
    background-size: clamp(1.9rem, 7.8vw, 2.6rem);
  }

  #chat {
    padding: 0.75rem 0.55rem 1rem;
    background-image: linear-gradient(180deg, rgba(255, 250, 242, 0.68), transparent 32%);
  }

  #chat .mes[is_user="true"] {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto;
    margin-bottom: 1.5rem;
  }

  #chat .mes[is_user="true"] .mesAvatarWrapper {
    grid-column: 1;
    grid-row: 1;
    width: 100%;
    min-height: 0;
    aspect-ratio: 16 / 9;
    border-left: 0;
    border-bottom: 1px solid var(--mj-line);
  }

  #chat .mes[is_user="true"] .mes_block {
    grid-column: 1;
    grid-row: 2;
    min-height: 0;
    padding: 1.35rem 1rem 1.55rem;
  }

  #chat .mes[is_user="false"][is_system="false"] {
    display: flex;
    width: 100%;
    max-width: 100%;
    inline-size: 100%;
    max-inline-size: 100%;
    padding-bottom: 2rem;
    margin-bottom: 1.6rem;
    flex-direction: column;
    align-items: stretch;
  }

  #chat .mes[is_user="false"][is_system="false"] > .mes_block {
    box-sizing: border-box;
    width: 100%;
    max-width: none;
    min-width: 0;
    inline-size: 100%;
    max-inline-size: none;
    min-inline-size: 0;
    padding-inline: 0;
    flex: 0 0 auto;
  }

  #chat .mes.last_mes[is_user="false"][is_system="false"] .mes_block::before,
  #chat .mes.last_mes[is_user="false"][is_system="false"] .mes_block::after {
    display: none;
    content: "";
  }

  #chat .mes[is_user="false"][is_system="false"] .ch_name {
    box-sizing: border-box;
    width: 100%;
    padding-inline: var(--mj-mobile-reading-padding);
  }

  #chat .mes[is_user="false"][is_system="false"] > .mes_block > .mes_text,
  #chat .mes[is_user="false"][is_system="false"] > .mes_block > .mes_reasoning_details {
    box-sizing: border-box;
    width: var(--mj-mobile-reading-width);
    max-width: 100%;
    inline-size: var(--mj-mobile-reading-width);
    max-inline-size: 100%;
    margin-inline: auto !important;
    padding-inline: var(--mj-mobile-reading-padding) !important;
  }

  #chat .mes_text { line-height: 1.94; }

  #form_sheld {
    min-width: 0;
    min-height: 0;
    height: auto;
  }

  #send_form {
    min-width: 0;
    min-height: 0;
    height: auto !important;
  }

  #send_form::before { inset: 0.25rem; }

  #send_form #nonQRFormItems {
    min-width: 0;
    align-items: center;
    flex-wrap: nowrap;
  }

  #send_form :is(#leftSendForm, #rightSendForm) {
    width: auto;
    height: auto;
    align-items: center;
    flex: 0 0 auto;
    flex-wrap: nowrap;
  }

  #send_form #send_textarea {
    width: 0;
    min-width: 0;
    min-height: var(--bottomFormBlockSize);
    height: auto !important;
    max-height: min(32dvh, 12rem);
    padding-block: 0.38rem;
    padding-inline: 0.65rem;
    align-self: center;
    flex: 1 1 auto;
    field-sizing: content;
    overflow-x: hidden;
    overflow-y: auto;
    font-size: 0.8rem;
    line-height: 1.5;
  }

  #send_form #send_textarea::placeholder {
    font-size: 0.8rem;
    line-height: 1.5;
  }

  #send_form :is(#options_button, #extensionsMenuButton, #send_but) {
    min-width: 2.75rem;
    min-height: 2.75rem;
    background-size: 2.35rem 2.35rem;
  }

  #send_form :is(#options_button, #extensionsMenuButton, #send_but):is(:hover, :focus-visible) {
    background-size: 2.5rem 2.5rem;
  }

  #send_form #extensionsMenuButton.fa-magic-wand-sparkles::before {
    width: 2.35rem;
    height: 2.35rem;
  }

  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup {
    border-radius: 0;
    box-shadow: none;
  }
}

/* ===== src/fallback.css ===== */
/* Remote assets remain decorative; labels, titles and pure-color structure stay usable. */
#chat .mes[is_user="false"][is_system="false"] .mes_block::after {
  background-color: transparent;
}

#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop) {
  font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", sans-serif;
}

#send_form :is(#options_button, #send_but)::before {
  color: var(--mj-red);
  opacity: 0.18;
}

#top-settings-holder .drawer-icon::after,
#send_form #send_textarea,
#chat .mes_text {
  font-family: var(--mj-font-body);
}
